-- Volcando estructura para procedimiento daimler26.PA_CORE_CapCatalogos
DELIMITER //
CREATE PROCEDURE `PA_CORE_CapCatalogos`(IN jsonParametros JSON)
sp:BEGIN
	DECLARE 	strOpcion 		   varchar(10) ;
	DECLARE 	strUsuario 		    VARCHAR(30);
	DECLARE 	strCodigo 		    varchar(10) ;
	DECLARE		strDetalle 		    varchar(255);	
	DECLARE		intEstatus 		    INT;
	DECLARE		intId			    BIGINT;
    DECLARE		intIdTipo		    BIGINT;
    DECLARE		blnActivo		    bit;
    DECLARE		strClaveCatalogo    varchar(10);
    DECLARE     strToken            Text;
    DECLARE     strTokenUser        Text;
    DECLARE		strAccion           varchar(30);
    DECLARE		strModulo           varchar(30) default 'jm_core';
    DECLARE		strPrograma         varchar(50)  default 'dai_catalogos';
	DECLARE		jsonAnterior 	    JSON;
    DECLARE     strMotivo           varchar(100);
    DECLARE     idRelacionCatalogos BIGINT;
    DECLARE     idTipoCat           BIGINT;  
    
	DECLARE CONTINUE HANDLER FOR SQLEXCEPTION 
		BEGIN
			SET intEstatus = 0;
			GET DIAGNOSTICS CONDITION 1 strCodigo = RETURNED_SQLSTATE, strDetalle = MESSAGE_TEXT;
		END;
	SET  lc_time_names = 'es_ES';
    
   select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Opcion')),
			JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Usuario')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.ClaveCatalogo')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.IdRelacionCatalogos')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.IdTipoCatalogo')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Catalogo.Id'))
	INTO  strOpcion, strUsuario, strClaveCatalogo, idRelacionCatalogos, idTipoCat, intId;

    Select USU_Token 
    From jm_core.core_usuarios USUARIO
    WHERE USUARIO.USU_Usuario = strUsuario
    Into strTokenUser;
    
    If (strOpcion Not IN ('VU', 'UT') And strTokenUser != strToken) Then
		SIGNAL SQLSTATE VALUE '45000'
		SET MESSAGE_TEXT = '¡El token no coincide!';
		SELECT  intId,intEstatus,strCodigo,strDetalle;
		leave sp;
    End If;
    
	IF (strOpcion = 'CC') THEN
		SELECT 
			CATALOGO.CAT_Id           AS Id,
			TIPO.CTT_Id               AS ID_TIPO,
			CATALOGO.CAT_Clave        AS CLAVE,
			UPPER(CATALOGO.CAT_Nombre) AS NOMBRE
		FROM dai_catalogos_tipo TIPO
			JOIN dai_catalogos CATALOGO
			ON TIPO.CTT_Id = CATALOGO.CTT_Id
		WHERE 
			CATALOGO.CAT_Activo = 1
			AND (
				(strClaveCatalogo IS NOT NULL AND TIPO.CTT_Clave = strClaveCatalogo)
				OR
				(idRelacionCatalogos IS NOT NULL AND CATALOGO.CAT_Relacion = idRelacionCatalogos AND TIPO.CTT_Id = idTipoCat)
			)
		ORDER BY CATALOGO.CAT_Id, NOMBRE;
	END IF;

    
    IF (strOpcion In ('C','CT')) THEN
		Select 	TIPO.CTT_Id as Id,
				TIPO.CTT_Clave as CLAVE,
                TIPO.CTT_Nombre as NOMBRE,
                TIPO.CTT_Descripcion as DESCRIPCION,
                TIPO.CTT_Usuario as USUARIO,
                TIPO.CTT_Fecha as FECHA
        From	dai_catalogos_tipo TIPO
        Order 	By Nombre;
	END IF;
     IF (strOpcion = 'CI') THEN
		Select 
             CATALOGOS.CAT_Id                       As Id,
			 CATALOGOS.CTT_Id                       As IdTipo,
			 CATALOGOS.CAT_Clave  					As CLAVE,
             CATALOGOS.CAT_Nombre 					As NOMBRE,
             CATALOGOS.CAT_Descripcion 				As DESCRIPCION,
             CATALOGOS.CAT_Usuario 					As USUARIO,
             CATALOGOS.CAT_Fecha 					As FECHA,
             /*CATALOGOS.CAT_UsuarioModifica   		As USUARIO_MODIFICA,
             CATALOGOS.CAT_FechaModifica     		As FECHA_MODIFICA,
             CATALOGOS.CAT_UsuarioElimina			As USUARIO_ELIMINA,
             CATALOGOS.CAT_FechaElimina				As FECHA_ELIMINA,
             CATALOGOS.CAT_MotivoEliminacion		As MOTIVO,*/
             CAST(CATALOGOS.CAT_Activo AS unsigned) As ACTIVO
        From dai_catalogos CATALOGOS
			Join dai_catalogos_tipo CATALOGOS_TIPO
				On CATALOGOS_TIPO.CTT_Id = CATALOGOS.CTT_Id
		Where CATALOGOS.CTT_Id = intId;
	END IF;
    IF (strOpcion='G') THEN
		select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Catalogo.Clave')),
				JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Catalogo.IdTipo'))
		INTO  strClaveCatalogo, intIdTipo;
		IF intId = 0 THEN
			IF (SELECT count(*) 
				FROM dai_catalogos CATALOGO 
                WHERE CATALOGO.CAT_Clave = strClaveCatalogo 
                And CATALOGO.CTT_Id=intIdTipo ) > 0 THEN
				SIGNAL SQLSTATE VALUE '99999'
				SET MESSAGE_TEXT = '¡Catalogo Existente!';
			END IF;	
        END IF;        
		START TRANSACTION;
		IF intId = 0 THEN  
			SET strAccion='crear';
				CAT_Clave,
				CAT_Nombre,
                CTT_Id,
				CAT_Descripcion,
				CAT_Fecha,
				CAT_Usuario,
				CAT_Activo
			)
			SELECT DISTINCT 
					Catalogo.Clave       as CAT_Clave,
					Catalogo.Nombre      as CAT_Nombre,
                    Catalogo.CLAVE_TIPO  as CTT_Id,
					Catalogo.Descripcion as CAT_Descripcion,
					now() 				 as CAT_Fecha,
					strUsuario 			 as CAT_Usuario,
                    1 					 as PER_Activo
			FROM JSON_TABLE(jsonParametros, '$.Catalogo'
					COLUMNS (
						CLAVE       varchar(15)  PATH '$.CLAVE', 
						NOMBRE      VARCHAR(50)  PATH '$.NOMBRE',
						CLAVE_TIPO  bigint       PATH '$.CLAVE_TIPO',
						DESCRIPCION	varchar(150) PATH '$.DESCRIPCION'
					)
				) AS Catalogo;
            Set intId = LAST_INSERT_ID();	
		ELSE
				SET strAccion = 'actualizar';
				Update dai_catalogos CATALOGO
				Join ( select 
						Id,
						CLAVE,
						NOMBRE,
                        IdTipo,
						DESCRIPCION,
						ACTIVO
				FROM JSON_TABLE(jsonParametros, '$.Catalogo'
					COLUMNS (
						Id		     bigint	     PATH '$.Id',
						CLAVE        VARCHAR(15)  PATH '$.CLAVE',
						NOMBRE       VARCHAR(50)  PATH '$.NOMBRE',
						IdTipo       Bigint       PATH '$.IdTipo',
						DESCRIPCION  VARCHAR(150) PATH '$.DESCRIPCION',
						ACTIVO       bit          PATH '$.ACTIVO'
					)
				) AS CATALOGO_UP )  AS CATALOGO_UP 
					  on CATALOGO.CAT_Id = CATALOGO_UP.Id
				SET CATALOGO.CAT_Clave             = CATALOGO_UP.CLAVE,
					CATALOGO.CAT_Nombre            = CATALOGO_UP.NOMBRE,
                    CATALOGO.CTT_Id                = CATALOGO_UP.IdTipo,
                    CATALOGO.CAT_Descripcion       = CATALOGO_UP.DESCRIPCION,
                    CATALOGO.CAT_UsuarioModifica   = strUsuario, 
                    CATALOGO.CAT_FechaModifica     = now(),
                    CATALOGO.CAT_Activo            = CATALOGO_UP.ACTIVO,
                    CATALOGO.CAT_UsuarioElimina    = null,
					CATALOGO.CAT_FechaElimina      = null,
					CATALOGO.CAT_MotivoEliminacion = null;
        END IF;

		IF intEstatus = 0 then
				ROLLBACK;
				call PA_dai_bitacoras(strModulo, strPrograma, "ErrorSQL", intId, jsonParametros, json_object("Error", strDetalle), strUsuario);
            	SELECT  intId, intEstatus, strCodigo, strDetalle;
        ELSE 
			 call PA_dai_bitacoras(strModulo, strPrograma, strAccion, intId, jsonAnterior, jsonParametros, strUsuario);
             Select intId As Id;
        	COMMIT;
      END IF;
	END IF;
    
    /* Consulta catalogo permisos */
    If(strOpcion = 'CCP') Then 
		SELECT CAT_Id     As Id,
               CAT_Nombre As NOMBRE
        FROM dai_catalogos
		Where CTT_Id = 2;
    End If; 
    
    /* Desactivar catalogos */
    If (strOpcion = 'DC') Then
		select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Catalogo.Motivo'))
		INTO  strMotivo;
        START TRANSACTION;
		Update dai_catalogos CATALOGO
				Join ( Select Id, Motivo
				FROM JSON_TABLE(jsonParametros, 
					   '$.Catalogo[*]' COLUMNS (
						Id		bigint 		 PATH '$.Id',
                        Motivo  varchar(100) PATH '$.Motivo'
					)
				) AS CATALOGO_UP )  AS CATALOGO_UP 
					  on CATALOGO.CAT_Id = CATALOGO_UP.Id
				SET  CATALOGO.CAT_MotivoEliminacion = CATALOGO_UP.Motivo,
                     CATALOGO.CAT_Activo            = 0,
                     CATALOGO.CAT_UsuarioElimina    = strUsuario,
                     CATALOGO.CAT_FechaElimina      = now();
			IF intEstatus = 0 then
				ROLLBACK;
				call PA_dai_bitacoras(strModulo, strPrograma, "ErrorSQL", intId, jsonParametros, json_object("Error", strDetalle), strUsuario);
            	SELECT  intId, intEstatus, strCodigo, strDetalle;
			ELSE 
				 call PA_dai_bitacoras(strModulo, strPrograma, strAccion, intId, jsonAnterior, jsonParametros, strUsuario);
				 Select intId As Id;
				COMMIT;
		  END IF;
	  END IF;
END//
DELIMITER ;

-- Volcando estructura para procedimiento daimler26.PA_CORE_CapCatalogoTipo
DELIMITER //
CREATE PROCEDURE `PA_CORE_CapCatalogoTipo`(IN jsonParametros JSON)
sp:BEGIN
	DECLARE 	strOpcion 		 varchar(10) ;
	DECLARE 	strUsuario 		 VARCHAR(30);
	DECLARE 	strCodigo 		 varchar(10) ;
	DECLARE		strDetalle 		 varchar(255);	
	DECLARE		intEstatus 		 INT ;
	DECLARE		intId			 BIGINT;
    DECLARE		intIdTipo		 BIGINT;
    DECLARE		blnActivo		 bit;
    DECLARE		strClaveCatalogo varchar(10);
    DECLARE     strToken         Text;
    DECLARE     strTokenUser     Text;
    DECLARE		strAccion        varchar(30);
    DECLARE		strModulo        varchar(30) default 'jm_core';
    DECLARE		strPrograma      varchar(50)  default 'core_catalogoTipo';
	DECLARE		jsonAnterior 	 JSON;
    DECLARE     strMotivo        varchar(100);
    
	DECLARE CONTINUE HANDLER FOR SQLEXCEPTION 
		BEGIN
			SET intEstatus = 0;
			GET DIAGNOSTICS CONDITION 1 strCodigo = RETURNED_SQLSTATE, strDetalle = MESSAGE_TEXT;
		END;
	SET  lc_time_names = 'es_ES';
    
   select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Opcion')),
			JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Usuario')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Catalogo.Id'))
	INTO  strOpcion,strUsuario,intId;

    Select USU_Token 
    From jm_core.core_usuarios USUARIO
    WHERE USUARIO.USU_Usuario = strUsuario
    Into strTokenUser;
    
    If (strOpcion Not IN ('VU', 'UT') And strTokenUser != strToken) Then
		SIGNAL SQLSTATE VALUE '45000'
		SET MESSAGE_TEXT = '¡El token no coincide!';
		SELECT  intId,intEstatus,strCodigo,strDetalle;
		leave sp;
    End If;
    
	If (strOpcion = 'CCT') Then 
		Select  CTT_Id                As Id,
				CTT_Clave             As CLAVE,
                CTT_Nombre            As NOMBRE,
                CTT_Descripcion       As DESCRIPCION,
                CTT_Usuario           As USUARIO,
                CTT_Fecha       	  As FECHA
                /*CTT_UsuarioModifica   As USUARIO_MODICIA,
                CTT_FechaModifica 	  As FECHA_MODIFICA,
                CTT_UsuarioElimina 	  As USUARIO_ELIMINA,
                CTT_FechaElimina 	  As FECHA_ELIMINA,
                CTT_MotivoEliminacion As MOTIVO_ELIMINACION*/
        From dai_catalogos_tipo
        Where CTT_Activo = 1;
    End If; 
    
    If (strOpcion = 'CTT') Then 
		Select  CTT_Id                As Id,
				CTT_Clave             As CLAVE,
                CTT_Nombre            As NOMBRE,
                CTT_Descripcion       As DESCRIPCION,
                CTT_Usuario           As USUARIO,
                CTT_Fecha       	  As FECHA,
                CTT_UsuarioModifica   As USUARIO_MODICIA,
                CTT_FechaModifica 	  As FECHA_MODIFICA,
                CTT_UsuarioElimina 	  As USUARIO_ELIMINA,
                CTT_FechaElimina 	  As FECHA_ELIMINA,
                CTT_MotivoEliminacion As MOTIVO_ELIMINACION
        From dai_catalogos_tipo;
    End If; 

    IF (strOpcion='G') THEN
		select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Catalogo.CLAVE'))
		INTO  strClaveCatalogo;
		IF intId = 0 THEN
			IF (SELECT count(*) FROM dai_catalogos_tipo CATALOGO 
				WHERE CATALOGO.CTT_Clave = strClaveCatalogo) > 0 THEN
				SIGNAL SQLSTATE VALUE '99999'
				SET MESSAGE_TEXT = '¡Catalogo Existente!';
			END IF;	
        END IF;        
		START TRANSACTION;
		
		IF intId = 0 THEN  
			SET strAccion='crear';
				CTT_Clave,
				CTT_Nombre,
				CTT_Descripcion,
				CTT_Fecha,
				CTT_Usuario,
                CTT_Activo
			)
			SELECT DISTINCT 
					Catalogo.Clave       as CTT_Clave,
					Catalogo.Nombre      as CTT_Nombre,
					Catalogo.Descripcion as CTT_Descripcion,
					now()                as CTT_Fecha,
					strUsuario           as CTT_Usuario,
                    1                    as CTT_Activo
			FROM JSON_TABLE(jsonParametros, '$.Catalogo'
					COLUMNS (
						Clave       varchar(15)  PATH '$.CLAVE', 
						Nombre      VARCHAR(50)  PATH '$.NOMBRE',
						Descripcion	varchar(150) PATH '$.DESCRIPCION'
					)
				) AS Catalogo;
            Set intId = LAST_INSERT_ID();	
		ELSE
				SET strAccion='actualizar';
				SELECT  json_object("CTT_Id",          CTT_Id,
                                    "CTT_Clave",       CTT_Clave,
                                    "CTT_Nombre",      CTT_Nombre,
                                    "CTT_Descripcion", CTT_Descripcion)
				FROM 	dai_catalogos_tipo CATALOGO
                where 	CATALOGO.CTT_Id = intId
				Into 	jsonAnterior;				
                
				Update dai_catalogos_tipo CATALOGO
				Join (Select Id,
							Clave,
                            Nombre,
                            Descripcion
				FROM JSON_TABLE(jsonParametros, '$.Catalogo'
					COLUMNS (
						Id		    bigint	     PATH '$.Id',
						Clave       varchar(15)  PATH '$.CLAVE', 
						Nombre      VARCHAR(50)  PATH '$.NOMBRE',
						Descripcion	varchar(150) PATH '$.DESCRIPCION'
					)
				) AS CATALOGO_UP )  AS CATALOGO_UP 
					  on CATALOGO.CTT_Id = CATALOGO_UP.Id
				SET CATALOGO.CTT_Id          = CATALOGO_UP.Id,
                    CATALOGO.CTT_Nombre      = CATALOGO_UP.Nombre,
                    CATALOGO.CTT_Descripcion = CATALOGO_UP.Descripcion;
        END IF;
		IF intEstatus = 0 then
				ROLLBACK;
				call PA_dai_bitacoras(strModulo, strPrograma, "ErrorSQL", intId, jsonParametros, json_object("Error", strDetalle), strUsuario);
            	SELECT  intId, intEstatus, strCodigo, strDetalle;
        ELSE 
			 call PA_dai_bitacoras(strModulo, strPrograma, strAccion, intId, jsonAnterior, jsonParametros, strUsuario);
             Select intId As Id;
        	COMMIT;
      END IF;
	END IF;
	/* Desactivar catalogos */
    If (strOpcion = 'DC') Then
		select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Catalogo.Motivo'))
		INTO  strMotivo;
        START TRANSACTION;
		Update dai_catalogos_tipo CATALOGO
				Join ( Select Id, Motivo
				FROM JSON_TABLE(jsonParametros, 
					   '$.Catalogo[*]' COLUMNS (
						Id		bigint 		 PATH '$.Id',
                        Motivo  varchar(100) PATH '$.Motivo'
					)
				) AS CATALOGO_UP )  AS CATALOGO_UP 
					  on CATALOGO.CTT_Id = CATALOGO_UP.Id
				SET  CATALOGO.CTT_MotivoEliminacion = CATALOGO_UP.Motivo,
                     CATALOGO.CTT_Activo            = 0,
                     CATALOGO.CTT_UsuarioElimina    = strUsuario,
                     CATALOGO.CTT_FechaElimina      = now();
			IF intEstatus = 0 then
				ROLLBACK;
				call PA_dai_bitacoras(strModulo, strPrograma, "ErrorSQL", intId, jsonParametros, json_object("Error", strDetalle), strUsuario);
            	SELECT  intId, intEstatus, strCodigo, strDetalle;
			ELSE 
				 call PA_dai_bitacoras(strModulo, strPrograma, strAccion, intId, jsonAnterior, jsonParametros, strUsuario);
				 Select intId As Id;
				COMMIT;
		  END IF;
	  END IF;
END//
DELIMITER ;

-- Volcando estructura para procedimiento daimler26.PA_CORE_ConMenu
DELIMITER //
CREATE PROCEDURE `PA_CORE_ConMenu`(IN jsonParametros JSON)
sp:BEGIN
	DECLARE 	strOpcion    varchar(10) ;
    DECLARE 	strUsuario   VARCHAR(30);
	DECLARE 	strCodigo    varchar(10) ;
	DECLARE		strDetalle   varchar(255);	
	DECLARE		intEstatus 		BOOL DEFAULT 1;
	
    DECLARE		strAccion varchar(30);
    DECLARE		strModulo    varchar(30) default 'laz_core';
    DECLARE		strPrograma  varchar(50)  default 'dai_perfiles';
	DECLARE		jsonAnterior JSON;
	DECLARE		intId		 BIGINT;
    DECLARE		blnActivo	 bit;
    DECLARE		strPassword  varchar(30);
    DECLARE		intIdPerfil  bigint;
    DECLARE     strToken     Text;
    DECLARE     strTokenUser Text;
    DECLARE     strNombre     VARCHAR(100);
    DECLARE     strIcono      VARCHAR(100);
    DECLARE     strMotivo     varchar(100);
    DECLARE     strPasswrod    varchar(30);
    DECLARE     intIdModulo    BIGINT;
    DECLARE     strPasswordPersonal varchar(50);
    
	DECLARE CONTINUE HANDLER FOR SQLEXCEPTION 
		BEGIN
			SET intEstatus = 0;
			GET DIAGNOSTICS CONDITION 1 strCodigo = RETURNED_SQLSTATE, strDetalle = MESSAGE_TEXT;
		END;
	SET  lc_time_names = 'es_ES';
	
   select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Opcion')),
	      JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Token')),
	      JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Usuario')),
          JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Modulo.Id'))
	INTO  strOpcion, strToken, strUsuario, intId;
    
     
		Select USU_Token 
		From dai_usuarios USUARIO
		WHERE USUARIO.USU_Usuario = strUsuario
		Into strTokenUser;
		
		If (strOpcion Not IN ('VU', 'UT') And strTokenUser != strToken) Then
			SIGNAL SQLSTATE VALUE '45000'
			SET MESSAGE_TEXT = '¡El token no coincide!';
			SELECT  intId,intEstatus,strCodigo,strDetalle;
		leave sp;
    End If;
        
        
	If (strOpcion = 'G') Then
        START TRANSACTION;
        If intId = 0 Then
			SET strAccion = 'Crear';
				
                MOD_Nombre,
                MOD_Icono,
                MOD_Usuario,
                MOD_Fecha,
                MOD_Activo,
                MOD_Orden
            )
         SELECT DISTINCT 
					Modulo.Nombre       As MOD_Nombre,
                    Modulo.Icono	    As MOD_Icono,
					strUsuario          As MOD_Usuario,
                    now()               As MOD_Fecha,
                    1                   As MOD_Activo,
                    11                  As MOD_Orden
			FROM JSON_TABLE(jsonParametros, '$.Modulo'
					COLUMNS (
						
						Nombre 		varchar(100) PATH '$.Nombre',
                        Icono	    varchar(100) PATH '$.Icono'
					)
				) AS Modulo;
			Set intId = last_insert_id();
        Else
		
        SET strAccion='actualizar';
			Update dai_modulos MODULOS
            Join (Select Id,Nombre, Icono
				From json_table(jsonParametros, '$.Modulo'
					columns (
						Id     bigint       PATH '$.Id',
						Nombre varchar(100) PATH '$.Nombre',
						Icono  varchar(100) PATH '$.Icono'
					)
				) As MODULOS_UP )  As MODULOS_UP
				On MODULOS.MOD_Id  = MODULOS_UP.Id
            Set MODULOS.MOD_Nombre = MODULOS_UP.Nombre,MODULOS.MOD_Icono  = MODULOS_UP.Icono;
       End If;
       
       
	   IF intEstatus=0 then
				ROLLBACK;
				call PA_dai_Bitacoras(strModulo,strPrograma,"ErrorSQL",intId,jsonParametros, json_object("Error", strDetalle),strUsuario);
            	SELECT  intId,intEstatus,strCodigo,strDetalle;
        ELSE 
			 call PA_dai_Bitacoras(strModulo,strPrograma,strAccion,intId,jsonAnterior,jsonParametros,strUsuario);
             Select intId As Id;
        	COMMIT;
      END IF;
      
    End If; 

    
    IF (strOpcion='VUS') THEN
	
         IF NOT  EXISTS(
				SELECT PERFIL.USU_Usuario
                FROM 	dai_usuarios_perfil PERFIL
                WHERE PERFIL.USU_Usuario= strUsuario ) 
          THEN
				SIGNAL SQLSTATE VALUE '99999'
				SET MESSAGE_TEXT = '¡Usuario sin perfil!';
                SELECT  intId,intEstatus,strCodigo,strDetalle;
                leave sp;
          
          END IF;
        
        Select 	MODULO.MOD_Id          as Id,
				MODULO.MOD_Nombre      as Nombre,
                MODULO.MOD_NombreMenu  as NombreMenu,
				MODULO.MOD_Icono       as Icono, 
                CAST(MODULO.MOD_Activo AS unsigned)  As Activo
		From	dai_modulos MODULO
        Order	By MODULO.MOD_Orden;
		
        Select Distinct
			PROGRAMAS.PRO_Id          As Id,
			PROGRAMAS.PRO_Nombre      As Nombre,
            PROGRAMAS.PRO_Descripcion As NombreMenu,
			PROGRAMAS.MOD_Id          As IdModulo,
			PROGRAMAS.PRO_Ruta 	      As Ruta,
            CAST(PROGRAMAS.PRO_Activo AS Unsigned) AS Activo
		From dai_perfiles PERFILES
			Join dai_perfiles_detalle PERFILES_DETALLE
				On PERFILES.PER_Id = PERFILES_DETALLE.PER_Id
			Join dai_programas_permiso PROGRAMA_PERMISO
				On PERFILES_DETALLE.CPP_Id = PROGRAMA_PERMISO.CPP_Id
			Join dai_programas PROGRAMAS
				On PROGRAMAS.PRO_Id = PROGRAMA_PERMISO.PRO_Id
			Join dai_catalogos CATALOGOS
				On CATALOGOS.CAT_Id = PROGRAMA_PERMISO.CAT_Permiso
			Join dai_usuarios_perfil USUARIOS
				On USUARIOS.PER_Id = PERFILES_DETALLE.PER_Id
		Where CATALOGOS.CAT_Clave = 'CON' AND USUARIOS.USU_Usuario = strUsuario;
        
	END IF;
    
    If (strOpcion = 'CM') Then
        Select 	MODULO.MOD_Id     as Id,
				MODULO.MOD_Nombre as Nombre,
				MODULO.MOD_Icono  as Icono, 
                CAST(MODULO.MOD_Activo AS unsigned)  As Activo
		From	dai_modulos MODULO
        Order	By MODULO.MOD_Orden;
    End If;
    
    /* VALIDAR USUARIO INICIO SESION */
	IF (strOpcion='VU') THEN	
    	select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Usuario')),
			JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Password'))
		INTO  strUsuario,strPasswrod;
        
        IF NOT  EXISTS(
				SELECT USUARIO.USU_Usuario
                FROM 	dai_usuarios USUARIO 
                WHERE USUARIO.USU_Usuario= strUsuario  AND USU_Password = MD5(strPasswrod) and USUARIO.USU_Activo=1) 
          THEN
				SIGNAL SQLSTATE VALUE '45000'
				SET MESSAGE_TEXT = '¡Credenciales Incorrectas!';
                SELECT  intId,intEstatus,strCodigo,strDetalle;
                leave sp;
          END IF;
    
            Select  USUARIO.USU_Usuario as USUARIO,
					USUARIO.USU_Nombre as NOMBRE,
                    USUARIO.USU_Correo as CORREO,
                    AREA.Nombre as AREA,
                    PUESTO.Nombre as PUESTO
            From 	dai_usuarios USUARIO
					left Join vwcatalogos PUESTO
						on Puesto.Id=USUARIO.CAT_Puesto
					left Join vwcatalogos AREA
						on Area.Id=USUARIO.CAT_Area
            WHERE 	USUARIO.USU_Usuario= strUsuario  AND USU_Password = MD5(strPasswrod);
      
     END IF;
     
     /* ACTUALIZA TOKEN */
     IF (strOpcion = 'UT') THEN
			
            Update dai_usuarios
            Set USU_Token = strToken
            Where USU_Usuario = strUsuario;
            
			Select USUARIO.USU_Token    	                   As TokenAPI,
				    USUARIO.USU_Usuario                        As UserActive,
                    USUARIO.USU_NombreInterno                  As NOMBRE,
                    USUARIO.USU_Correo  	   				   As CORREO,
                    USUARIO.USU_Imagen                         As IMG,
                    AREA.Nombre                				   As AREA,
                    PUESTO.Nombre                              As PUESTO,
                    CAST(USUARIO.USU_UsuarioNuevo As unsigned) As USUARIO_NUEVO
            From dai_usuarios USUARIO 
				left Join vwcatalogos PUESTO
					on Puesto.Id = USUARIO.CAT_Puesto
				left Join vwcatalogos AREA
					on Area.Id = USUARIO.CAT_Area
            WHERE USUARIO.USU_Usuario = strUsuario;
     END IF;
     
     /* ACTUALIZAR CONTRASEÑA PERSONAL */
     If(strOpcion = 'UP') Then 
		Select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Password'))
        Into strPasswordPersonal;
        START TRANSACTION;
        Update dai_usuarios
        Set USU_Password = MD5(strPasswordPersonal),
			USU_UsuarioNuevo = 0
        Where USU_Usuario    = strUsuario 
			AND USU_Password <> MD5(strPasswordPersonal);
		SET intEstatus = ROW_COUNT();
        Select intEstatus as ESTATUS;
        IF intEstatus = 0 then
			ROLLBACK;
			SET strDetalle = 'La nueva contraseña no puede ser igual a la actual';
			CALL PA_dai_Bitacoras(
				strModulo, strPrograma, 'ErrorSQL',
				intId, jsonParametros,
				JSON_OBJECT('Error', strDetalle), strUsuario
			);
			SELECT intId, intEstatus, 'ERR' AS strCodigo, strDetalle;
        ELSE 
			 call PA_dai_Bitacoras(strModulo,strPrograma,strAccion,intId,jsonAnterior,jsonParametros,strUsuario);
             Select intId As Ids;
        	COMMIT;
      END IF;
     End If;
END//
DELIMITER ;

-- Volcando estructura para procedimiento daimler26.PA_dai_bitacoras
DELIMITER //
CREATE PROCEDURE `PA_dai_bitacoras`(IN strModulo varchar(30),IN strPrograma varchar(30), IN strAccion varchar(30),IN intId bigint,IN jsonAnterior JSON, IN jsonNuevo JSON, IN strUsuario varchar(30))
BEGIN
	  BIT_Modulo ,
      BIT_Programa,
      BIT_Accion,
	  BIT_IdReferencia,
      BIT_JsonAnterior,
      BIT_JsonNuevo,
      BIT_Usuario,
      BIT_Fecha
    )
    Select	strModulo,
			strPrograma,
            strAccion,
            intId,
            jsonAnterior,
            jsonNuevo,
            strUsuario,
            now();

END//
DELIMITER ;

-- Volcando estructura para procedimiento daimler26.PA_DAI_Empleados
DELIMITER //
CREATE PROCEDURE `PA_DAI_Empleados`(IN jsonParametros JSON)
BEGIN
	DECLARE 	strOpcion varchar(10) ;
	DECLARE 	strUsuario VARCHAR(30);
	DECLARE 	strCodigo varchar(10) ;
	DECLARE		strDetalle varchar(255);	
	DECLARE		intEstatus INT ;
	DECLARE		intIdEmpleado BIGINT;
	DECLARE		intId			BIGINT;
    DECLARE		intIdPaquete	BIGINT;
    DECLARE 	dteFechaIngreso date;
    DECLARE		blnActivo		bit;
    DECLARE		intFirmaGafete 	bigint;
    DECLARE		dteFechaEntrega	date;
	DECLARE		intTallaCamisa	bigint;	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION 
	BEGIN 
		rollback;
		GET DIAGNOSTICS CONDITION 1 strCodigo = RETURNED_SQLSTATE, strDetalle= MESSAGE_TEXT;
		SELECT 200 as intEstatus,strCodigo,strDetalle as strDetalle;
	END;
	DECLARE EXIT HANDLER FOR 99999
	BEGIN 
		rollback;
		GET DIAGNOSTICS CONDITION 1 strCodigo = RETURNED_SQLSTATE, strDetalle = MESSAGE_TEXT;
		SELECT 200 as intEstatus,strCodigo,strDetalle;
	END;
	SET  lc_time_names = 'es_ES';
	Select JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Opcion')),
   			JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Usuario')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Empleado.EMP_FirmaGafete')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Empleado.EMP_Id')),
            JSON_UNQUOTE(JSON_EXTRACT( jsonParametros,'$.Empleado.CAT_TallaCamisa'))
	INTO  strOpcion,strUsuario,intFirmaGafete,intIdEmpleado,intTallaCamisa;
    
    IF (strOpcion='G') THEN
		START TRANSACTION;
		SET AUTOCOMMIT=0;
		
		 Update dai_empleados EMPLEADOS
			Join ( select EMP_Id,CAT_TallaCamisa,CAT_TallaPantalon,EMP_Comentarios
             FROM JSON_TABLE(jsonParametros, '$.Empleado'
				COLUMNS (
		    EMP_Id  BIGINT PATH '$.EMP_Id', 
		    CAT_TallaCamisa bigint  PATH '$.CAT_TallaCamisa',
            CAT_TallaPantalon bigint  PATH '$.CAT_TallaPantalon',
		    EMP_Comentarios VARCHAR(150) PATH '$.EMP_Comentarios'
						)
			)AS TALLAS )  AS TALLAS 
				  on TALLAS.EMP_Id=EMPLEADOS.EMP_Id
        SET EMPLEADOS.CAT_TallaCamisa=TALLAS.CAT_TallaCamisa , EMPLEADOS.CAT_TallaPant=TALLAS.CAT_TallaPantalon,EMPLEADOS.EMP_ComentariosTomaTalla=TALLAS.EMP_Comentarios,EMPLEADOS.EMP_FechaTomaTalla=now();
  
      /* Update dai_empleados EMPLEADOS
			Join ( select EMP_Id,CAT_TallaSudadera,EMP_Comentarios
             FROM JSON_TABLE(jsonParametros, '$.Empleado'
				COLUMNS (
		    EMP_Id  BIGINT PATH '$.EMP_Id', 
		    CAT_TallaSudadera bigint  PATH '$.CAT_TallaSudadera',
		    EMP_Comentarios VARCHAR(150) PATH '$.EMP_Comentarios'
						)
			)AS TALLAS )  AS TALLAS 
				  on TALLAS.EMP_Id=EMPLEADOS.EMP_Id
        SET EMPLEADOS.CAT_TallaSudadera=TALLAS.CAT_TallaSudadera ,EMPLEADOS.EMP_ComentariosTomaTalla=TALLAS.EMP_Comentarios,EMPLEADOS.EMP_FechaTomaTalla=now();
            */
       
       COMMIT;

 /*
			Update dai_empleados set CAT_TallaCamisa=intTallaCamisa
			WHERE EMP_Id=intIdEmpleado;
            */
        Select 'ok' as strCodigo,'¡Información Guardada Correctamente!' as strDetalle;
        
	END IF;
    
    IF (strOpcion='C') THEN
		SELECT 	EMPLEADOS.EMP_Id              As Id,
				EMPLEADOS.EMP_NumeroEmpleado  As NUMERO_EMPLEADO,
				EMPLEADOS.EMP_Nombre 		  As NOMBRE, 
                EMPLEADOS.EMP_Badge 		  As BADGE,
                EMPLEADOS.EMP_Usuario         As USUARIO,
                EMPLEADOS.EMP_Fecha           As FECHA,
                CAST(EMPLEADOS.EMP_Activo as unsigned) As ACTIVO
				/*AREA.CAT_Nombre as AREA,
				IFNULL(TURNO.CAT_NOMBRE,'') AS TURNO,
				PUESTO.CAT_NOMBRE AS PUESTO
				/*IFNULL(TALLA_CAMISA.CAT_Clave,'') AS CAMISA,
				IFNULL(TALLA_PANTALON.CAT_Clave,'')AS PANTALON,
                IFNULL(TALLA_SUDADERA.CAT_Clave,'')AS SUDADERA,
                EMPLEADOS.EMP_ComentariosTomaTalla AS COMENTARIOS*/
		FROM 	dai_empleados EMPLEADOS
				/*Join DAI_CATALOGOS AREA
					ON EMPLEADOS.CAT_Area=AREA.CAT_Id
				Join DAI_CATALOGOS PUESTO
					ON EMPLEADOS.CAT_Puesto=PUESTO.CAT_Id
				Left Join DAI_CATALOGOS TURNO 
					ON EMPLEADOS.CAT_Turno=TURNO.CAT_Id
				Left JoIN dai_catalogos TALLA_CAMISA
					on TALLA_CAMISA.CAT_Id=ifnull(EMPLEADOS.CAT_TallaCamisa,0)
				Left JoIN dai_catalogos TALLA_PANTALON
					on TALLA_PANTALON.CAT_Id=ifnull(EMPLEADOS.CAT_TallaPant,0)
				Left JoIN dai_catalogos TALLA_SUDADERA
					on TALLA_SUDADERA.CAT_Id=ifnull(EMPLEADOS.CAT_TallaSudadera,0)*/
			Where EMPLEADOS.EMP_Activo = 1;
	END IF;
	
    IF (strOpcion='CI') THEN
		Select EMPLEADOS.EMP_FechaIngreso,EMPLEADOS.PAQ_Id,EMPLEADOS.EMP_Activo,EMPLEADOS.EMP_Id,EMPLEADOS.EMP_FechaEntrega FROM dai_empleados EMPLEADOS WHERE EMPLEADOS.EMP_FirmaGafete = intFirmaGafete or EMPLEADOS.EMP_Id=intIdEmpleado
        Into dteFechaIngreso,intIdPaquete,blnActivo,intIdEmpleado,dteFechaEntrega;
		
        IF (SELECT count(*) FROM dai_empleados EMPLEADOS WHERE EMPLEADOS.EMP_Id = intIdEmpleado )=0 THEN
			SIGNAL SQLSTATE VALUE '99999'
			SET MESSAGE_TEXT = '¡No existe el empleado!';
		END IF;
       /*  IF  year(dteFechaIngreso)=YEAR(now())  THEN
			SIGNAL SQLSTATE VALUE '99999'
			SET MESSAGE_TEXT = '¡No se puede realizar la entrega por la fecha de ingreso!';
		END IF;
        */
        SELECT 		EMPLEADOS.EMP_Id as Id,
					EMPLEADOS.EMP_NumeroEmpleado as NUMERO_EMPLEADO,
                    EMPLEADOS.EMP_FirmaGafete as FIRMA_GAFETE,
                    EMPLEADOS.EMP_Nombre	as NOMBRE_EMPLEADO,
                    AREA.CAT_NOMBRE			AS AREA,
                    PUESTO.CAT_NOMBRE 		AS PUESTO,
                    DATE_FORMAT(EMPLEADOS.EMP_FechaIngreso,"%d %M %Y") as FECHA_INGRESO
		FROM 		dai_empleados EMPLEADOS 			
					Join dai_catalogos AREA
						on AREA.CAT_Id=EMPLEADOS.CAT_Area
					Join dai_catalogos PUESTO
						on PUESTO.CAT_Id=EMPLEADOS.CAT_PUESTO   
		WHERE		EMPLEADOS.EMP_Id=intIdEmpleado;
        
		 Select CATALOGO.CAT_Id as Id,
				CATALOGO.CAT_CLAVE AS NOMBRE
		From 	dai_catalogos_tipo CATALOGO_TIPO
				Join dai_catalogos CATALOGO
					on CATALOGO.CTT_Id=CATALOGO_TIPO.CTT_Id
				Join dai_catalogos_extras CATALOGO_EXTRA
					on CATALOGO_EXTRA.CAT_Id=CATALOGO.CAT_Id and CATALOGO_EXTRA.CAX_Tipo='Division' and CATALOGO_EXTRA.CAX_Valor='Top'
		Where	CATALOGO_TIPO.CTT_Clave='TALL'
		order by CATALOGO.CAT_Orden;
		
        Select 	CATALOGO.CAT_Id as Id,
				CATALOGO.CAT_CLAVE AS NOMBRE
		From 	dai_catalogos_tipo CATALOGO_TIPO
				Join dai_catalogos CATALOGO
					on CATALOGO.CTT_Id=CATALOGO_TIPO.CTT_Id
				Join dai_catalogos_extras CATALOGO_EXTRA
					on CATALOGO_EXTRA.CAT_Id=CATALOGO.CAT_Id and CATALOGO_EXTRA.CAX_Tipo='Division' and CATALOGO_EXTRA.CAX_Valor='Pant'
		Where	CATALOGO_TIPO.CTT_Clave='TALL'
		order by CATALOGO.CAT_Orden;
    END IF;
END//
DELIMITER ;

-- Volcando estructura para vista daimler26.vwcatalogos
-- Creando tabla temporal para superar errores de dependencia de VIEW
CREATE TABLE `vwcatalogos` (
	`Id` BIGINT(20) NOT NULL,
	`Clave` VARCHAR(10) NULL COLLATE 'latin1_swedish_ci',
	`Nombre` VARCHAR(45) NULL COLLATE 'latin1_swedish_ci',
	`Descripcion` VARCHAR(100) NULL COLLATE 'latin1_swedish_ci',
	`Activo` BIT(1) NULL,
	`ClaveTipo` VARCHAR(10) NULL COLLATE 'latin1_swedish_ci'
) ENGINE=MyISAM;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vwcatalogos`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vwcatalogos` AS select `catalogo`.`CAT_Id` AS `Id`,`catalogo`.`CAT_Clave` AS `Clave`,`catalogo`.`CAT_Nombre` 
AS `Nombre`,`catalogo`.`CAT_Descripcion` AS `Descripcion`,`catalogo`.`CAT_Activo` AS `Activo`,`tipo`.`CTT_Clave` AS `ClaveTipo`
 from (`dai_catalogos_tipo` `tipo` join `dai_catalogos` `catalogo` on(`catalogo`.`CTT_Id` = `tipo`.`CTT_Id`)) ;

